import pandas as pd
import pdfplumber
import json

def clean_currency(val):
    if isinstance(val, str):
        return int(val.replace(',', ''))
    return val

def clean_int(val):
    return int(val)

def clean_float(val):
    return float(val)

# 1. Read Excel (Current Data)
df_excel = pd.read_excel('/root/employees_current.xlsx')
# Ensure ID is string
df_excel['ID'] = df_excel['ID'].astype(str)

# Convert Excel dataframe to a dict of dicts for easy lookup: {ID: {col: val, ...}}
