excel_records = {}
for _, row in df_excel.iterrows():
    rec = row.to_dict()
    # explicit type conversion for consistency
    rec['Salary'] = int(rec['Salary'])
    rec['Years'] = int(rec['Years'])
    rec['Score'] = float(rec['Score'])
    excel_records[rec['ID']] = rec

# 2. Read PDF (Old Data)
pdf_rows = []
with pdfplumber.open('/root/employees_backup.pdf') as pdf:
    for page in pdf.pages:
        table = page.extract_table()
        if table:
