    # Map row to dictionary
    record = dict(zip(header, row))
    pdf_data.append(record)

# Clean PDF data and build dict
pdf_records = {}
for rec in pdf_data:
    emp_id = rec['ID']

    # Type conversion to match Excel
    try:
        rec['Salary'] = clean_currency(rec['Salary'])
        rec['Years'] = clean_int(rec['Years'])
        rec['Score'] = clean_float(rec['Score'])
    except ValueError as e:
        print(f"Skipping malformed row for {emp_id}: {e}")
        continue

    pdf_records[emp_id] = rec

# 3. Compare
deleted_employees = []
modified_employees = []

# Check for deleted (in PDF but not in Excel)
for emp_id in pdf_records:
    if emp_id not in excel_records:
        deleted_employees.append(emp_id)

# Check for modifications (in both)
columns_to_compare = ['First', 'Last', 'Dept', 'Position', 'Salary', 'Years', 'Location', 'Score']

for emp_id, old_rec in pdf_records.items():
    if emp_id in excel_records:
        new_rec = excel_records[emp_id]
        for field in columns_to_compare:
            old_val = old_rec[field]
            new_val = new_rec[field]

